from modele import *
from donnees_figures import triangle,schema

def R(i,t,e,c,m,k,values=('','','')):
    return E(t,e,c,m,k,figure=triangle(f'trigo-{i:02}',valeurs=values))

chapitre(14,'trigonometrie','Trigonométrie du triangle rectangle','4 · Géométrie',
'Cosinus · Sinus · Tangente · Longueurs · Angles',
['Choisir le rapport adapté à l’angle et aux données.','Calculer une longueur ou un angle aigu.','Rédiger et contrôler un problème de mesure.'],['Pythagore et proportionnalité.'],[
r'''\essSection{1}{Trois rapports pour un angle aigu}
\begin{definition}Dans ABC rectangle en A, pour l’angle $\widehat B$, BC est l’hypoténuse, AB le côté adjacent et AC le côté opposé. Les deux derniers rôles s’échangent si l’on choisit l’angle C.\end{definition}
\begin{propriete}$\cos\widehat B=AB/BC$, $\sin\widehat B=AC/BC$ et $\tan\widehat B=AC/AB$. Ces rapports dépendent de l’angle, pas de la taille du triangle : des triangles rectangles ayant le même angle aigu sont semblables.\end{propriete}
\begin{savoirfaire}[Trouver une longueur]Écrire le rapport avec les noms des côtés avant de remplacer. Si BC = 10 cm et $\widehat B=35^\circ$, $AC=10\sin35^\circ\approx5{,}74$ cm. Si AB = 10 cm, on utiliserait $AC=10\tan35^\circ$.\end{savoirfaire}
\begin{attention}La calculatrice doit être en mode degrés. Un sinus ou cosinus d’angle aigu est entre 0 et 1 ; une hypoténuse reste le plus long côté.\end{attention}''',
r'''\essSection{2}{Angles et problèmes}
\begin{savoirfaire}[Trouver un angle]Si AB = 6 cm et BC = 10 cm, $\cos\widehat B=0{,}6$. Utiliser la fonction inverse du cosinus, souvent notée $\cos^{-1}$ ou acos : $\widehat B\approx53{,}1^\circ$. Cette touche ne calcule pas $1/\cos$.\end{savoirfaire}
\begin{propriete}Les deux angles aigus d’un triangle rectangle ont pour somme $90^\circ$. Cette relation fournit un contrôle ou un autre moyen de calcul.\end{propriete}
\begin{savoirfaire}[Une mesure indirecte]Pour une hauteur inaccessible, dessiner l’horizontale au niveau de l’observateur et sa ligne de visée. La hauteur calculée par tangente est celle au-dessus de cette horizontale ; ajouter ensuite la hauteur de l’instrument si nécessaire.\end{savoirfaire}
\begin{attention}Conserver les valeurs de calculatrice non arrondies jusqu’à la dernière étape. Préciser l’unité et la précision demandée. Un angle observé et une distance mesurés restent des données de modèle, avec une précision limitée.\end{attention}'''],[
R(1,'Nommer les côtés',r"ABC est rectangle en A. Pour l’angle B, identifier le côté opposé, l’adjacent et l’hypoténuse.",r"Le côté opposé est $\res{AC}$, l’adjacent est $\res{AB}$ et l’hypoténuse est $\res{BC}$. AB touche B mais n’est pas l’hypoténuse.","Commencer par l’hypoténuse.","assert {'AC','AB','BC'}==set(['AC','AB','BC'])"),
R(2,'Choisir le cosinus',r"ABC est rectangle en A. AB = 6 cm et BC = 10 cm. Donner $\cos B$.",r"$\cos B=AB/BC=6/10=\res{0{,}6}$. Le rapport utilise l’adjacent et l’hypoténuse.","Écrire les noms des côtés avant les nombres.","assert Rational(6,10)==Rational('.6')",('6 cm','','10 cm')),
R(3,'Choisir le sinus',r"ABC est rectangle en A. AC = 8 cm et BC = 10 cm. Donner $\sin B$.",r"$\sin B=AC/BC=8/10=\res{0{,}8}$. AC est opposé à B.","Repérer le côté qui ne touche pas l’angle B.","assert Rational(8,10)==Rational('.8')",('','8 cm','10 cm')),
R(4,'Choisir la tangente',r"ABC est rectangle en A. AB = 6 cm et AC = 8 cm. Donner $\tan B$.",r"$\tan B=AC/AB=8/6=\res{4/3}$. Une tangente peut dépasser 1, contrairement au sinus ou au cosinus d’un angle aigu.","La tangente ne fait pas intervenir l’hypoténuse.","assert Rational(8,6)==Rational(4,3)",('6 cm','8 cm','')),
R(5,'Une première longueur',r"ABC est rectangle en A, B = 30 degrés et BC = 12 cm. Calculer AC.",r"$AC=BC\sin30^\circ=12\times0{,}5=\res{6\text{ cm}}$. Le côté opposé est la moitié de l’hypoténuse pour cet angle.","Isoler la longueur dans le rapport.","assert 12*sin(pi/6)==6",('','','12 cm')),
R(6,'Un côté adjacent',r"ABC est rectangle en A. B = 40 degrés et BC = 9 cm. Calculer AB au millimètre.",r"$AB=9\cos40^\circ\approx6{,}8944$ cm, donc $\res{AB\approx6{,}9\text{ cm}}$ au millimètre. Le millimètre représente 0,1 cm.","Relier la précision à l’unité de travail.","assert round(9*math.cos(math.radians(40)),1)==6.9",('?','','9 cm')),
R(7,'Une hypoténuse',r"ABC est rectangle en A. B = 50 degrés et AB = 7 cm. Calculer BC au dixième de centimètre.",r"$\cos50^\circ=7/BC$, donc $BC=7/\cos50^\circ\approx\res{10{,}9\text{ cm}}$. Multiplier par le cosinus aurait donné un côté trop court.","Résoudre l’égalité avant de calculer.","assert round(7/math.cos(math.radians(50)),1)==10.9",('7 cm','','?')),
R(8,'Un angle par cosinus',r"ABC est rectangle en A, AB = 6 cm et BC = 10 cm. Calculer B au degré.",r"$\cos B=0{,}6$. La fonction inverse donne $B\approx53{,}13^\circ$, donc $\res{B\approx53^\circ}$. L’angle C vaut alors environ 37 degrés.","Utiliser la fonction inverse en mode degrés.","assert round(math.degrees(math.acos(.6)))==53",('6 cm','','10 cm')),
R(9,'Un angle par tangente',r"ABC est rectangle en A, AC = 5 cm et AB = 12 cm. Calculer B au dixième de degré.",r"$\tan B=5/12$, donc $B=\arctan(5/12)\approx\res{22{,}6^\circ}$. L’opposé est inférieur à l’adjacent : un angle inférieur à 45 degrés est cohérent.","Choisir le rapport contenant les deux données.","assert round(math.degrees(math.atan(5/12)),1)==22.6",('12 cm','5 cm','')),
R(10,'Changer d’angle',r"ABC est rectangle en A, AB = 9 cm, AC = 12 cm, BC = 15 cm. Donner $\sin B$ et $\cos C$. Expliquer leur égalité.",r"$\sin B=12/15=4/5$ et $\cos C=12/15=4/5$. Le côté opposé à B est adjacent à C ; les deux angles sont complémentaires.","Réidentifier les côtés quand l’angle change.","assert Rational(12,15)==Rational(4,5)",('9 cm','12 cm','15 cm')),
E('La hauteur d’un bâtiment',r"Un appareil à 1,6 m du sol vise le sommet d’un bâtiment avec un angle d’élévation de 32 degrés. Il est à 25 m horizontalement du pied. Le sol est horizontal. Calculer la hauteur au décimètre.",r"Au-dessus de l’appareil, la hauteur vaut $25\tan32^\circ\approx15{,}6217$ m. En ajoutant 1,6 m, la hauteur totale est $\res{17{,}2\text{ m}}$ au décimètre. Oublier la hauteur de visée sous-estimerait le résultat.","Séparer hauteur au-dessus de la visée et hauteur totale.","assert round(25*math.tan(math.radians(32))+1.6,1)==17.2",figure='trigo-batiment'),
R(12,'Une rampe et son angle',r"Une rampe monte de 0,8 m pour 10 m d’avancée horizontale. Dans ABC, A est l’angle droit, AB l’avancée et AC la hauteur. Calculer l’angle B au dixième et la pente définie par $100AC/AB$.",r"$B=\arctan(0{,}8/10)\approx\res{4{,}6^\circ}$. La pente est $\res{8\,\%}$. 8 \% ne signifie donc pas un angle de 8 degrés.","Distinguer pourcentage de pente et mesure angulaire.","assert round(math.degrees(math.atan(.08)),1)==4.6 and Rational('.8')/10*100==8",('10 m','0,8 m','')),
R(13,'Un câble',r"Un câble BC de 18 m fait un angle B de 65 degrés avec le sol horizontal AB. AC est vertical. Calculer la hauteur AC et la distance AB au dixième de mètre.",r"$AC=18\sin65^\circ\approx\res{16{,}3\text{ m}}$ et $AB=18\cos65^\circ\approx\res{7{,}6\text{ m}}$. Les calculs non arrondis vérifient Pythagore.","Calculer les deux projections de l’hypoténuse.","assert round(18*math.sin(math.radians(65)),1)==16.3 and round(18*math.cos(math.radians(65)),1)==7.6",('?','?','18 m')),
E('Un toit symétrique',r"Le toit a pour section un triangle isocèle de base 8 m ; chaque versant fait 35 degrés avec l’horizontale. Calculer sa hauteur puis la longueur d’un versant au centimètre.",r"La hauteur partage la base en deux segments de 4 m. Elle vaut $4\tan35^\circ\approx\res{2{,}80\text{ m}}$. Un versant mesure $4/\cos35^\circ\approx\res{4{,}88\text{ m}}$. On utilise 4 m, pas la base entière.","Exploiter la symétrie pour obtenir un triangle rectangle.","assert round(4*math.tan(math.radians(35)),2)==2.80 and round(4/math.cos(math.radians(35)),2)==4.88",figure='trigo-toit'),
R(15,'Diagnostiquer une erreur',r"ABC est rectangle en A. B = 38 degrés, AB = 7 cm. Un élève annonce AC = $7\sin38^\circ$. Corriger puis donner AC au dixième.",r"AB est adjacent et AC opposé à B ; leur rapport est la tangente. $\tan38^\circ=AC/7$, donc $\res{AC=7\tan38^\circ\approx5{,}5\text{ cm}}$. Le sinus exigerait l’hypoténuse au dénominateur.","Contrôler les côtés du rapport, pas seulement le résultat.","assert round(7*math.tan(math.radians(38)),1)==5.5",('7 cm','?',''))
],reperes=['Choisir cosinus, sinus ou tangente','Calculer une longueur','Calculer un angle aigu','Mesures indirectes et contrôle du modèle'],deco='geometrie')

def H(i,t,e,c,m,k,fig=None):
    return E(t,e,c,m,k,figure=fig or f'transfo-{i:02}')

chapitre(15,'transformations','Transformations et homothéties','4 · Géométrie',
'Symétries · Translation · Rotation · Homothétie · Motifs',
['Reconnaître et construire une image par transformation.','Utiliser les rapports positifs et négatifs d’homothétie.','Étudier longueurs, aires et volumes.'],['Repérage, angles et proportionnalité.'],[
r'''\essSection{1}{Déplacer ou retourner une figure}
\begin{definition}La symétrie axiale d’axe d associe à A un point A’ tel que d est la médiatrice de [AA’], sauf si A est sur d : alors A’ = A. La symétrie centrale de centre O fait de O le milieu de [AA’].\end{definition}
\begin{definition}Une translation est un glissement défini par une direction, un sens et une distance, par exemple l’envoi d’un point P sur Q. Une rotation de centre O et d’angle donné fait tourner chaque point autour de O, avec un sens précisé.\end{definition}
\begin{propriete}Symétries, translations et rotations conservent longueurs, angles, alignements, aires et parallélisme. Une symétrie axiale retourne l’orientation du motif ; une rotation ou une translation la conserve.\end{propriete}
\begin{savoirfaire}[Construire]Reporter les points remarquables puis les relier dans le même ordre. Une rotation exige même distance au centre et angle orienté correct. Une translation reproduit le même déplacement pour tous les points, sans faire tourner la figure.\end{savoirfaire}''',
r'''\essSection{2}{Agrandir ou réduire}
\begin{definition}Une homothétie de centre O et de rapport $k\ne0$ envoie A sur A’ avec O, A, A’ alignés et $OA'=|k|\,OA$. Si $k>0$, A et A’ sont sur la même demi-droite issue de O ; si $k<0$, ils sont de part et d’autre de O. O reste fixe.\end{definition}
\begin{propriete}Les longueurs sont multipliées par $|k|$, les aires par $k^2$, les volumes par $|k|^3$. Une droite ne passant pas par O a pour image une droite parallèle. Les angles sont conservés.\end{propriete}
\begin{exemple}Pour $k=-2$, l’image est deux fois plus grande en longueurs, de l’autre côté du centre. Son aire est quatre fois plus grande et son volume huit fois plus grand. Pour $k=-1$, on retrouve la symétrie centrale.\end{exemple}
\begin{savoirfaire}[Frises, pavages, rosaces]Une frise répète un motif par translations suivant une direction. Un pavage recouvre le plan sans trou ni chevauchement. Une rosace organise des rotations autour d’un centre. Rechercher la transformation qui relie les motifs.\end{savoirfaire}'''],[
H(1,'Une symétrie axiale',r"Dans le repère, A(2;1), B(4;1), C(3;3). Construire leurs images par rapport à l’axe vertical des ordonnées.",r"On garde l’ordonnée et on change le signe de l’abscisse : $\res{A'(-2;1),B'(-4;1),C'(-3;3)}$. L’axe est la médiatrice des trois segments point-image.","Reporter perpendiculairement de l’autre côté de l’axe.","assert [(-a,b) for a,b in [(2,1),(4,1),(3,3)]]==[(-2,1),(-4,1),(-3,3)]"),
H(2,'Une symétrie centrale',r"O est l’origine et A(3;2). Construire l’image A’ par la symétrie de centre O.",r"O est le milieu de [AA’], donc $\res{A'(-3;-2)}$. Les deux coordonnées changent de signe.","Placer le centre au milieu du segment.","assert (3+(-3),2+(-2))==(0,0)"),
H(3,'Une translation',r"La translation envoie P(0;0) sur Q(3;1). Donner l’image du triangle A(1;2), B(3;2), C(2;4).",r"Chaque point se déplace de trois unités vers la droite et d’une vers le haut. $\res{A'(4;3),B'(6;3),C'(5;5)}$. Les côtés gardent longueurs et directions.","Répéter le même déplacement pour tous les sommets.","assert [(a+3,b+1) for a,b in [(1,2),(3,2),(2,4)]]==[(4,3),(6,3),(5,5)]"),
H(4,'Un quart de tour',r"Dans le repère orthonormé, faire tourner A(3;1) de 90 degrés autour de O dans le sens inverse des aiguilles d’une montre.",r"Le quart de tour donne $\res{A'(-1;3)}$. On vérifie $OA^2=10=OA'^2$ et l’angle de 90 degrés dans le sens demandé.","Respecter le sens et conserver la distance au centre.","assert 3**2+1**2==(-1)**2+3**2"),
H(5,'Longueurs conservées',r"Un triangle a pour côtés 4 cm, 6 cm et 7 cm. Quel est le périmètre de son image par une rotation de 120 degrés ?",r"Une rotation conserve chaque longueur. Le périmètre reste $4+6+7=\res{17\text{ cm}}$, indépendamment de l’angle de rotation.","Utiliser l’invariance plutôt que mesurer le dessin.","assert 4+6+7==17"),
H(6,'Rapport positif',r"O est l’origine, A(2;1), B(3;0), C(1;3). Construire l’image par l’homothétie de centre O et rapport 2.",r"Chaque coordonnée est doublée : $\res{A'(4;2),B'(6;0),C'(2;6)}$. Les images restent sur les mêmes demi-droites issues de O.","Doubler les distances au centre sans changer de côté.","assert [(2*a,2*b) for a,b in [(2,1),(3,0),(1,3)]]==[(4,2),(6,0),(2,6)]"),
H(7,'Rapport négatif',r"Reprendre A(2;1), B(3;0), C(1;3) et construire l’image par l’homothétie de centre O, origine, de rapport $-1{,}5$.",r"On multiplie les coordonnées par $-1{,}5$ : $\res{A'(-3;-1{,}5),B'(-4{,}5;0),C'(-1{,}5;-4{,}5)}$. Les images sont de l’autre côté du centre, à 1,5 fois la distance.","Le signe règle le côté ; la valeur absolue règle la longueur.","assert [(-Rational(3,2)*a,-Rational(3,2)*b) for a,b in [(2,1),(3,0),(1,3)]]==[(-3,-Rational(3,2)),(-Rational(9,2),0),(-Rational(3,2),-Rational(9,2))]"),
H(8,'Retrouver le rapport',r"O, A et A’ sont alignés, OA = 4 cm et OA’ = 10 cm. A et A’ sont de part et d’autre de O. Quel est le rapport ?",r"La valeur absolue est $10/4=2{,}5$. Les points sont de côtés opposés : $\res{k=-2{,}5}$. Une distance OA’ n’est pourtant jamais négative.","Distinguer rapport signé et longueur positive.","assert abs(Rational(-5,2))*4==10"),
H(9,'Périmètre et aire',r"Une figure a pour périmètre 18 cm et pour aire 20 cm$^2$. Une homothétie a pour rapport $-3$. Calculer le périmètre et l’aire de l’image.",r"Les longueurs sont multipliées par 3 : périmètre $\res{54\text{ cm}}$. L’aire est multipliée par $(-3)^2=9$ : $\res{180\text{ cm}^2}$. Aucun résultat de mesure n’est négatif.","Appliquer le facteur adapté à la dimension.","assert 18*3==54 and 20*(-3)**2==180"),
H(10,'Reconnaître une réduction',r"Une maquette est l’image d’un solide par un rapport de 0,4. Le volume initial est 750 cm$^3$. Calculer le volume réduit.",r"Le facteur des volumes est $0{,}4^3=0{,}064$. Le volume vaut $750\times0{,}064=\res{48\text{ cm}^3}$. Employer 0,4 seul conviendrait aux longueurs.","Élever le rapport au cube pour le volume.","assert 750*Rational('.4')**3==48"),
H(11,'Une frise',r"Un motif est répété horizontalement tous les 4 cm. Quelle transformation envoie un motif sur le suivant ? Quelle distance entre un point du premier motif et son homologue dans le sixième ?",r"Il s’agit d’une translation horizontale de 4 cm vers la droite. Entre les motifs 1 et 6, il y a cinq déplacements : $\res{20\text{ cm}}$.","Compter les intervalles entre motifs.","assert (6-1)*4==20"),
H(12,'Une rosace',r"Une rosace est formée de huit copies régulièrement réparties d’un motif autour de O. Quel angle de rotation envoie une copie sur la suivante ? Après trois pas ?",r"Un pas vaut $360/8=\res{45^\circ}$. Trois pas valent $\res{135^\circ}$ dans le sens choisi. Huit pas ramènent au départ.","Partager le tour complet en parts égales.","assert 360/8==45 and 3*45==135"),
H(13,'Retrouver un centre',r"A(1;1) a pour image A’(3;3) et B(3;1) a pour image B’(7;3) par une homothétie de rapport 2. Déterminer son centre O.",r"Les droites AA’ et BB’ se coupent en $\res{O(-1;-1)}$. On vérifie que A est le milieu de OA’ et B le milieu de OB’ : $(O+A')/2=A$ et $(O+B')/2=B$, coordonnée par coordonnée.","Croiser les droites point-image puis contrôler le rapport.","assert ((-1+3)/2,(-1+3)/2)==(1,1) and ((-1+7)/2,(-1+3)/2)==(3,1)"),
H(14,'Une aire donne-t-elle le signe ?',r"Deux triangles homothétiques ont des aires de 12 cm$^2$ et 75 cm$^2$. Donner les rapports possibles du premier vers le second. Peut-on choisir le signe sans connaître leurs positions ?",r"$k^2=75/12=25/4$. Donc $\res{k=2{,}5\text{ ou }k=-2{,}5}$. L’aire ne permet pas de choisir le signe ; il faut savoir de quel côté du centre sont les sommets homologues.","Une information d’aire fixe seulement la valeur absolue.","assert Rational(75,12)==Rational(5,2)**2"),
H(15,'Deux transformations successives',r"Une figure subit deux homothéties de même centre O : rapport $-2$, puis rapport $-0{,}5$. Décrire l’image finale d’un point A différent de O.",r"Le premier changement place le point de l’autre côté à distance $2OA$. Le second change encore de côté et multiplie cette distance par 0,5. Le point revient exactement en A. Le rapport global vaut $\res{(-2)(-0{,}5)=1}$.","Suivre séparément côté du centre et distance.","assert (-2)*Rational(-1,2)==1")
],reperes=['Symétries, translations et rotations','Homothéties de rapports positifs et négatifs','Facteurs de longueurs, aires et volumes','Frises, pavages et rosaces'],deco='geometrie')

def V(i,t,e,c,m,k,fig=None):
    return E(t,e,c,m,k,figure=fig or f'espace-{i:02}')

chapitre(16,'espace','Espace, solides et repérage sur la sphère','4 · Géométrie',
'Perspectives · Patrons · Sections · Volumes · Latitude et longitude',
['Interpréter plusieurs représentations d’un solide.','Calculer des volumes et des assemblages.','Se repérer dans un pavé et sur une sphère.'],['Aires usuelles, Pythagore et unités de volume.'],[
r'''\essSection{1}{Représenter et mesurer les solides}
\begin{savoirfaire}[Lire une représentation]Une perspective cavalière représente les arêtes cachées en pointillés. Les longueurs dessinées ne sont pas toutes les longueurs réelles. Une vue de face ou de dessus projette les formes ; une section est l’intersection avec un plan. Un patron permet de replier les faces sans chevauchement.\end{savoirfaire}
\begin{propriete}Pour un pavé : $V=L\ell h$. Pour un prisme droit ou un cylindre : $V=\mathcal A_{\rm base}h$. Pour une pyramide ou un cône : $V=\mathcal A_{\rm base}h/3$. La hauteur est perpendiculaire à la base.\end{propriete}
\begin{propriete}Pour une boule de rayon r : $V=4\pi r^3/3$. Pour sa surface, la sphère : $\mathcal A=4\pi r^2$. Un diamètre vaut deux rayons.\end{propriete}
\begin{savoirfaire}[Assembler]Décomposer en solides usuels, additionner des volumes sans recouvrement ou soustraire un creux. Conserver $\pi$ jusqu’au résultat final. Pour un réservoir, convertir ensuite en litres.\end{savoirfaire}''',
r'''\essSection{2}{Sections et repérages}
\begin{propriete}La section d’un pavé par un plan parallèle à une face est un rectangle de mêmes dimensions que cette face. La section d’une boule par un plan est un disque ; son contour sur la sphère est un cercle. Le cercle est maximal quand le plan passe par le centre.\end{propriete}
\begin{savoirfaire}[Un repère dans un pavé]Fixer une origine et trois directions d’arêtes perpendiculaires. Les coordonnées $(x;y;z)$ donnent trois déplacements. Préciser l’unité et les limites de chaque coordonnée.\end{savoirfaire}
\begin{definition}Sur une sphère terrestre, la latitude indique un angle au nord ou au sud de l’équateur, de 0 à 90 degrés. La longitude indique un angle à l’est ou à l’ouest du méridien d’origine, de 0 à 180 degrés. Les pôles ont une latitude de 90 degrés ; leur longitude n’est pas unique.\end{definition}
\begin{attention}Deux points de même latitude appartiennent au même parallèle ; de même longitude, au même méridien. Une carte plane peut déformer distances et aires. Les exercices géographiques donnent des positions fictives ou un modèle explicite.\end{attention}'''],[
V(1,'Un pavé',r"Un pavé a pour dimensions 8 cm, 5 cm et 3 cm. Calculer son volume.",r"$V=8\times5\times3=\res{120\text{ cm}^3}$. Les trois dimensions sont exprimées dans la même unité.","Multiplier les trois dimensions perpendiculaires.","assert 8*5*3==120"),
V(2,'Un cylindre',r"Un cylindre a un rayon de 3 cm et une hauteur de 10 cm. Donner son volume exact et au cm$^3$.",r"$V=\pi\times3^2\times10=\res{90\pi\text{ cm}^3}\approx\res{283\text{ cm}^3}$. Le rayon est déjà fourni, il ne faut pas le diviser par deux.","Calculer l’aire du disque de base.","assert 3**2*10==90 and round(90*math.pi)==283"),
V(3,'Une pyramide',r"Une pyramide a une base carrée de côté 6 cm et une hauteur de 9 cm. Calculer son volume.",r"L’aire de base vaut 36 cm$^2$. Le volume vaut $36\times9/3=\res{108\text{ cm}^3}$. La division par trois distingue la pyramide du prisme de même base et hauteur.","Utiliser la hauteur perpendiculaire.","assert 6**2*9/3==108"),
V(4,'Un cône',r"Un cône a pour diamètre 8 cm et hauteur 9 cm. Calculer son volume exact.",r"Le rayon est 4 cm. $V=\pi\times4^2\times9/3=\res{48\pi\text{ cm}^3}$. Employer 8 comme rayon multiplierait le résultat par quatre.","Passer du diamètre au rayon.","assert 4**2*9/3==48"),
V(5,'Une boule',r"Une boule a un rayon de 3 cm. Donner son volume et l’aire de sa sphère, sous forme exacte.",r"$V=4\pi\times27/3=\res{36\pi\text{ cm}^3}$. L’aire vaut $4\pi\times9=\res{36\pi\text{ cm}^2}$. Les valeurs numériques des coefficients coïncident ici, mais les grandeurs et unités diffèrent.","Ne pas confondre aire et volume.","assert Rational(4,3)*3**3==36 and 4*3**2==36"),
V(6,'Lire un patron de cube',r"Le patron comporte six carrés de côté 2 cm. Nommer les faces opposées à A, B et C après pliage ; calculer l’aire totale du cube.",r"La bande horizontale B-C-D-E s’enroule : B est opposée à D, C à E. A et F ferment les extrémités et sont opposées. L’aire totale vaut $6\times2^2=\res{24\text{ cm}^2}$.","Simuler le pliage sans confondre proximité sur la feuille et sur le cube.","assert 6*2**2==24",fig='espace-patron'),
V(7,'Trois vues',r"Un pavé a une longueur de 8 cm, une profondeur de 5 cm et une hauteur de 3 cm. Donner les dimensions des vues de face, de dessus et du côté droit.",r"La face montre $\res{8\times3}$ cm, le dessus $\res{8\times5}$ cm et le côté $\res{5\times3}$ cm. La profondeur n’apparaît pas dans la vue de face.","Associer chaque vue aux dimensions visibles.","assert 8*3==24 and 8*5==40 and 5*3==15",fig='espace-vues'),
V(8,'Une section de pavé',r"Un pavé de base 8 cm sur 5 cm et de hauteur 6 cm est coupé par un plan parallèle à la base à 2 cm de celle-ci. Quelle forme et quelle aire a la section ?",r"La section est un rectangle de dimensions 8 cm sur 5 cm. Son aire vaut $\res{40\text{ cm}^2}$. La hauteur de coupe ne modifie pas cette section parallèle dans un pavé.","Reconnaître une section parallèle à une face.","assert 8*5==40",fig='espace-section-pave'),
V(9,'Des coordonnées dans un pavé',r"Dans le pavé de dimensions 6, 4, 3 unités, O est l’origine ; les axes suivent longueur, profondeur, hauteur. Donner le sommet opposé à O et la projection de P(2;3;1) sur le plan de base.",r"Le sommet opposé a pour coordonnées $\res{(6;4;3)}$. La projection verticale garde les deux premières coordonnées et annule la hauteur : $\res{(2;3;0)}$. P est bien à l’intérieur des trois limites.","Identifier le rôle des trois coordonnées.","assert 0<2<6 and 0<3<4 and 0<1<3",fig='espace-repere'),
V(10,'Latitude et longitude',r"Les points fictifs A et B ont pour positions $(35^\circ\text{ N};20^\circ\text{ E})$ et $(35^\circ\text{ N};50^\circ\text{ O})$. Sont-ils sur le même parallèle ? Le même méridien ? Quelle est la différence de longitude ?",r"Ils ont la même latitude : même parallèle. Leurs longitudes diffèrent : méridiens distincts. Ils sont de part et d’autre de l’origine des longitudes, donc l’écart vaut $20+50=\res{70^\circ}$. Cet angle n’est pas une distance en kilomètres.","Distinguer latitude, longitude et distance.","assert 20+50==70",fig='espace-sphere'),
V(11,'Un réservoir assemblé',r"Un réservoir fermé est formé d’un cylindre de rayon 1 m et de hauteur 2 m, surmonté d’une demi-boule de même rayon. Calculer sa capacité au litre.",r"Le cylindre vaut $2\pi$ m$^3$, la demi-boule $2\pi/3$ m$^3$. Le total est $8\pi/3$ m$^3$, soit $8000\pi/3$ L, environ $\res{8378\text{ L}}$. Les deux parties ne se recouvrent qu’à leur frontière.","Additionner les volumes puis convertir.","assert round(8000*math.pi/3)==8378",fig='espace-reservoir'),
V(12,'Une boule creusée',r"Une boule pleine de rayon 5 cm contient une cavité sphérique de rayon 2 cm, entièrement intérieure. Quel volume de matière reste-t-il ?",r"On soustrait les volumes : $V=4\pi(5^3-2^3)/3=4\pi\times117/3=\res{156\pi\text{ cm}^3}$. Il faut soustraire des cubes, pas calculer le volume d’un rayon $5-2$.","Soustraire les volumes du plein et du creux.","assert Rational(4,3)*(5**3-2**3)==156",fig='espace-cavite'),
V(13,'Une section de sphère',r"Une sphère de centre O a un rayon de 5 cm. Un plan la coupe à une distance OH = 3 cm du centre ; H est le centre du cercle de section. Calculer le rayon de ce cercle et l’aire du disque.",r"Pour M sur le cercle, OHM est rectangle en H. $HM^2=OM^2-OH^2=25-9=16$, donc $\res{HM=4\text{ cm}}$. Le disque a pour aire $\res{16\pi\text{ cm}^2}$.","Passer par le triangle rectangle de la section.","assert 5**2-3**2==4**2",fig='espace-section-sphere'),
V(14,'Un cône réduit',r"Un cône de rayon 6 cm et hauteur 12 cm est coupé parallèlement à sa base à mi-hauteur. Le petit cône de même sommet a un rapport de réduction $1/2$. Calculer son volume et celui du tronc restant.",r"Le grand volume vaut $\pi\times36\times12/3=144\pi$ cm$^3$. Le petit vaut $(1/2)^3\times144\pi=\res{18\pi\text{ cm}^3}$. Le tronc vaut $144\pi-18\pi=\res{126\pi\text{ cm}^3}$.","Utiliser le cube du rapport puis soustraire.","assert 144*Rational(1,2)**3==18 and 144-18==126",fig='espace-cone-coupe'),
V(15,'La diagonale de l’espace',r"Un pavé mesure 3 cm, 4 cm et 12 cm. Calculer une diagonale de la base 3 par 4 puis une diagonale intérieure joignant deux sommets opposés.",r"La diagonale de base vaut $\sqrt{3^2+4^2}=5$ cm. Avec la hauteur de 12 cm, un autre triangle rectangle donne $\sqrt{5^2+12^2}=\res{13\text{ cm}}$. Deux applications successives de Pythagore suffisent.","Construire d’abord une diagonale de face.","assert 3**2+4**2==5**2 and 5**2+12**2==13**2",fig='espace-diagonale')
],reperes=['Perspectives, patrons, vues et sections','Volumes usuels, boule et assemblages','Repérage dans un pavé','Latitude et longitude sur une sphère'],deco='espace')
